'use strict';

function add(a, b) {
  return a + b;
}

function sub(a, b) {
  return a - b;
}

// helpers
function clamp(x) {
  return x;
}

function noop() {
  return;
}

function twice(x) {
  return x;
}

function mul(a, b) {
  return a * b;
}

module.exports = { add, sub, clamp, noop, twice, mul };

